import { ChevronLeft, ChevronRight, type LucideProps } from 'lucide-react-native';
import type { ComponentType, ReactNode } from 'react';
import { I18nManager, Pressable, type PressableProps, View } from 'react-native';

import { cn } from '@/lib/utils';

import { Icon } from './icon';
import { Text } from './text';

export interface ListItemProps extends PressableProps {
  title: string;
  subtitle?: string;
  icon?: ComponentType<LucideProps>;
  right?: ReactNode;
  showChevron?: boolean;
  className?: string;
}

/** A tappable settings/list row with optional leading icon, trailing content, chevron. */
export function ListItem({
  title,
  subtitle,
  icon,
  right,
  showChevron = false,
  className,
  ...props
}: ListItemProps) {
  return (
    <Pressable
      accessibilityRole={props.onPress ? 'button' : undefined}
      className={cn('min-h-[52px] flex-row items-center gap-3 px-4 py-3', className)}
      {...props}
    >
      {icon ? <Icon as={icon} className="text-muted-foreground" size={20} /> : null}
      <View className="flex-1">
        <Text>{title}</Text>
        {subtitle ? <Text className="text-xs text-muted-foreground">{subtitle}</Text> : null}
      </View>
      {right}
      {showChevron ? (
        <Icon
          as={I18nManager.isRTL ? ChevronLeft : ChevronRight}
          className="text-muted-foreground"
          size={18}
        />
      ) : null}
    </Pressable>
  );
}
